svg.script:
const colors = ['#2563eb', '#16a34a', '#dc2626', '#7c3aed'];
let n = 0;
document.getElementById('dot').addEventListener('click', () => {
  n += 1;
  document.getElementById('dot').setAttribute('fill', colors[n % colors.length]);
  document.getElementById('count').textContent = n + (n === 1 ? ' click' : ' clicks');
});
